python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
 def __init__(self): super().__init__(); self.a=[]
 def handle_data(self,d):
  d=' '.join(d.split())
  if d:self.a.append(d)
for f in ['/tmp/ddg.html','/tmp/topos.html','/tmp/aj.html','/tmp/catlab.html','/tmp/ad.html']:
 p=P(); p.feed(Path(f).read_text(errors='ignore')); text='\n'.join(p.a)
 print('\n===== '+f)
 for term in ['Catlab','Algebraic','composit','wiring','C-set','ACSet','operad','cospan','open system','Topos']:
  hits=[x for x in text.splitlines() if term.lower() in x.lower()]
  if hits: print('\n--'+term+'--'); print('\n'.join(hits[:12]))
PY
